import{_ as e,o as c,a as t,b as _}from"./app.UgfkfLuP.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API<a npu_parse_enabled=\\"true\\"></a>","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"矩阵计算","link":"/api/SIMD-API/c_api/cube_compute/cube_compute"},{"text":"矩阵计算分形介绍","link":"/api/SIMD-API/c_api/cube_compute/cube_compute_fractal_intro/cube_compute_fractal_intro"},{"text":"背景与核心概念","link":"/api/SIMD-API/c_api/cube_compute/cube_compute_fractal_intro/background_and_core_concepts"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cube_compute/cube_compute_fractal_intro/background_and_core_concepts.md","filePath":"api/SIMD-API/c_api/cube_compute/cube_compute_fractal_intro/background_and_core_concepts.md","lastUpdated":1791622466000}'),o={name:"api/SIMD-API/c_api/cube_compute/cube_compute_fractal_intro/background_and_core_concepts.md"};function r(p,a,n,i,u,l){return c(),t("div",null,[...a[0]||(a[0]=[_('<div><article class="markdown-body"><h1>背景与核心概念</h1><p>矩阵计算单元采用分块计算逻辑，例如可并行处理16×16的矩阵分片。在传统的线性存储布局（如row major（行主序）或column major（列主序））中，数据按行或列连续存放。当需要读取一个16×16的矩形数据块时，若直接从内存中获取，则需访问不连续的多个内存地址以逐行“收集”数据，这种非连续访问会导致内存效率显著下降。</p><p>为解决上述问题，引入了矩阵分形存储格式。该格式通过软件层对数据进行重排，使每个16×16计算块在物理内存中连续存放。硬件仅需发起一次连续读取，即可将整个数据块加载至片上寄存器，避免了多地址寻址开销，从而大幅提升矩阵计算单元的数据吞吐率。</p><p>昇腾AI处理器的矩阵计算单元为追求极高的数据吞吐率与计算密度，采用了专有的硬件架构设计。与通用CPU常用的连续线性存储不同，该单元要求输入输出数据必须符合特定的分形存储格式。在使用Ascend C的asc_mmad类接口进行算子开发时，深入理解这些数据格式对于实现正确的数据搬运、分块及性能优化至关重要。</p><p>为便于理解与记忆，文档采用“大Y小x”的直观命名法：</p><ul><li>大Y（Z/N）：表示分形矩阵之间的排列顺序（Z为row major（行主序），N为column major（列主序））。</li><li>小x（z/n）：表示分形矩阵内部元素的排列顺序（z为row major（行主序），n为column major（列主序））。</li></ul><p>矩阵A、B、C在各存储层级中的具体排布参见<a href="key_fractal_format_details.html">关键分形格式详解</a>；Bias、Scale和稀疏索引等辅助数据参见<a href="aux_cube_fractal_format_details.html">辅助矩阵分形格式详解</a>。</p></article></div>',1)])])}const s=e(o,[["render",r]]);export{d as __pageData,s as default};
